# Generated by build.py from recipe.yml for recipe ldaps-search-over-tls. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/.surl/ldap
cat > site/.surl/ldap/directory.ldif <<'EOF'
dn: dc=example,dc=com
objectClass: domain
dc: example

dn: cn=alice,dc=example,dc=com
objectClass: person
cn: alice
sn: Liddell
mail: alice@example.com

dn: cn=bob,dc=example,dc=com
objectClass: person
cn: bob
sn: Builder
mail: bob@example.com
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site --cert server.pem --key server.key --user alice:s3cret ldaps://127.0.0.1:8080/ ldap://127.0.0.1:8081/ &
sleep 1
curl -k -u alice:s3cret "ldaps://127.0.0.1:8080/dc=example,dc=com?mail?sub?(cn=bob)"
kill $(jobs -p)
